ALTER TABLE google_health.history_work ADD COLUMN replace_missing boolean NOT NULL DEFAULT false;
ALTER TABLE google_health.history_child ADD COLUMN query_fingerprints jsonb, ADD COLUMN validated bigint;
CREATE INDEX idx_google_health_reload_request ON google_health.history_audit
    (account_id,data_type,representation,calendar_policy,key_policy,native_day,end_bound)
    WHERE outcome='RELOAD_REQUESTED';
